/***************************************************************************************************** 
 *
 * Given the head of a linked list, remove the nth node from the end of the list and return its head.
 * 
 * Follow up: Could you do this in one pass?
 * 
 * Example 1:
 * 
 * Input: head = [1,2,3,4,5], n = 2
 * Output: [1,2,3,5]
 * 
 * Example 2:
 * 
 * Input: head = [1], n = 1
 * Output: []
 * 
 * Example 3:
 * 
 * Input: head = [1,2], n = 1
 * Output: [1]
 * 
 * Constraints:
 * 
 * 	The number of nodes in the list is sz.
 * 	1 <= sz <= 30
 * 	0 <= Node.val <= 100
 * 	1 <= n <= sz
 ******************************************************************************************************/

/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode() {}
 *     ListNode(int val) { this.val = val; }
 *     ListNode(int val, ListNode next) { this.val = val; this.next = next; }
 * }
 */
class Solution {
    public ListNode removeNthFromEnd(ListNode head, int n) {
        if (head == null || n <= 0) {
            return head;
        }

        ListNode dummy = new ListNode(0, head);

        ListNode pre = dummy, fast = dummy;
        while (n-- >= 0) {
            fast = fast.next;
        }

        while (fast != null) {
            pre = pre.next;
            fast = fast.next;
        }

        pre.next = pre.next.next;

        return dummy.next;
    }
}

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* removeNthFromEnd(ListNode* head, int n) {
        ListNode* pre = new ListNode(0);
        pre -> next = head;

        ListNode* slow = pre;
        ListNode* fast = pre;

        for(int i=0; i<=n; i++)
        fast = fast -> next;

        while(fast){
            slow = slow -> next;
            fast = fast -> next;
        }

        slow -> next = slow -> next -> next;

        return pre -> next;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* removeNthFromEnd(ListNode* head, int n) {
        auto ptr= head;
        int size=1;
        while(ptr->next!=NULL){
            ptr=ptr->next;
            size++;
        }
        ptr=head;
        if(size==1)
            head=NULL;
        else if(size==n){
            auto temp=head;
            head=head->next;
        }
        else{
            int i=1;
            while(i!=size-n){
                i++;
                ptr=ptr->next;
            }
            auto temp=ptr->next->next;
            ptr->next=temp;
        }
        return head;
    }
};

